	private static void awaitReaderAtPublicationBarrier(Thread reader, Future<?> admitted) throws Exception {
		assertThat(reader).isNotNull();
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(8);
		StackTraceElement[] last = new StackTraceElement[0];
		do {
			if (admitted.isDone()) {
				admitted.get();
				throw new AssertionError("reader admitted before the executing publication callback completed");
			}
			last = reader.getStackTrace();
			boolean atPublication = Arrays.stream(last)
					.anyMatch(frame -> frame.getClassName().equals(LmdbSailStore.class.getName())
							&& frame.getMethodName().equals("awaitStablePublication"));
			boolean conditionWait = Arrays.stream(last)
					.anyMatch(frame -> frame.getClassName().endsWith("AbstractQueuedSynchronizer$ConditionObject")
							&& frame.getMethodName().equals("await"));
			if (reader.getState() == Thread.State.WAITING && atPublication && conditionWait) {
				return;
			}
			Thread.yield();
		} while (System.nanoTime() < deadline);
		throw new AssertionError("reader never reached the actual publication condition: " + Arrays.toString(last));
	}

	private static Plans capturePlans(NativeLmdbQuerySource source) throws IOException {
		LmdbPrefixRunPlan prefix = source.prefixRunPlan(new int[] { TripleIndex.PRED_IDX }, -1, -1, -1, -1);
		assertThat(prefix).isNotNull();
		LmdbRootScanPartition[] partitions = source.planRootScanPartitions(-1, -1, -1, -1, 4);
		assertThat(partitions).isNotEmpty();
		return new Plans(prefix, partitions);
	}

	private static void assertPlans(NativeLmdbQuerySource source, Plans plans, Set<Quad> expected) throws IOException {
		assertThat(source.count(-1, -1, -1, -1)).as("snapshot-local count, not global cardinality")
				.isEqualTo(expected.size());
		long count = 0;
		try (LmdbPrefixRunCursor runs = source.prefixRuns(plans.prefix(), -1, -1, -1, -1, true)) {
			while (runs.next()) {
				count += runs.runRowCount();
			}
		}
		assertThat(count).isEqualTo(expected.size());
		Set<Quad> actual = new HashSet<>();
		for (LmdbRootScanPartition partition : plans.partitions()) {
			try (RecordIterator records = source.statements(-1, -1, -1, -1, partition)) {
				for (long[] quad; (quad = records.next()) != null;) {
					assertThat(actual.add(new Quad(quad[0], quad[1], quad[2], quad[3], true)))
							.as("snapshot-local root partitions are disjoint")
							.isTrue();
				}
			}
		}
		assertThat(actual).isEqualTo(expected);
	}

	private static void assertParallelSnapshot(NativeLmdbQuerySource source, Set<Quad> expected, boolean required)
			throws IOException {
		NativeLmdbQuerySource.ParallelSource[] siblings = source.openParallelSources(1);
		if (required) {
			assertThat(siblings).as("the current snapshot admits a matching sibling").isNotNull();
		}
		if (siblings != null) {
			assertThat(siblings).hasSize(1);
			try (NativeLmdbQuerySource.ParallelSource sibling = siblings[0]) {
				assertPlans(sibling, capturePlans(sibling), expected);
			}
		}
	}

	private static Set<Quad> rawModel(NativeLmdbQuerySource source, Set<Statement> statements) {
		Set<Quad> result = statements.stream()
				.map(statement -> new Quad(source.idOf(statement.getSubject()),
						source.idOf(statement.getPredicate()), source.idOf(statement.getObject()),
						statement.getContext() == null ? 0 : source.idOf(statement.getContext()), true))
				.collect(Collectors.toSet());
		assertThat(result).hasSize(statements.size()).allSatisfy(quad -> {
			assertThat(quad.subject()).isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
			assertThat(quad.predicate()).isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
			assertThat(quad.object()).isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
			assertThat(quad.context()).isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
		});
		return result;
	}

	private static void assertStatements(SailDataset dataset, Set<Statement> expected) {
		Set<Statement> actual = new HashSet<>();
		try (var statements = dataset.getStatements(null, null, null)) {
			while (statements.hasNext()) {
				assertThat(actual.add(statements.next())).as("no duplicate statement").isTrue();
			}
		}
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
	}

	private static Statement statement(int row) {
		var values = SimpleValueFactory.getInstance();
		return values.createStatement(values.createIRI("urn:publication:subject:" + row),
				values.createIRI("urn:publication:predicate"), values.createLiteral("object:" + row),
				row % 2 == 0 ? values.createIRI("urn:publication:context") : null);
	}

	private static void write(LmdbSailStore backing, Set<Statement> statements) {
		try (SailSink sink = backing.getExplicitSailSource().sink(IsolationLevels.NONE)) {
			for (Statement statement : statements) {
				sink.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(),
						statement.getContext());
			}
			sink.flush();
		}
	}

	private static Throwable capture(Runnable operation) {
		try {
			operation.run();
			return null;
		} catch (Throwable failure) {
			return failure;
		}
	}

	private static void throwFailure(Throwable failure) {
		if (failure instanceof Error error) {
			throw error;
		}
		throw (RuntimeException) failure;
	}

	private static void restore(String property, String value) {
		if (value == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
	}

	private record Plans(LmdbPrefixRunPlan prefix, LmdbRootScanPartition[] partitions) {
	}

	private enum Outcome {
		SUCCESS,
		STRICT_NONFATAL,
		FATAL
	}

	private static final class Gate {
		final CountDownLatch entered = new CountDownLatch(1);
		final CountDownLatch release = new CountDownLatch(1);

		void block() {
			entered.countDown();
			try {
				assertThat(release.await(30, TimeUnit.SECONDS)).as("release the certified commit boundary").isTrue();
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				throw new AssertionError("interrupted at commit boundary", interrupted);
			}
		}

		void awaitEntered() throws InterruptedException {
			assertThat(entered.await(10, TimeUnit.SECONDS)).as("the real commit boundary executes").isTrue();
		}
	}
